#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int shareCandies(std::vector<int>& candies, int k) {
        std::unordered_map<int, int> freq;
        for (int c : candies) freq[c]++;

        int n = candies.size();
        for (int i = 0; i < k; ++i) {
            if (--freq[candies[i]] == 0) freq.erase(candies[i]);
        }

        int maxUnique = freq.size();

        for (int i = k; i < n; ++i) {
            freq[candies[i - k]]++;
            if (--freq[candies[i]] == 0) freq.erase(candies[i]);
            maxUnique = std::max(maxUnique, (int)freq.size());
        }
        return maxUnique;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int shareCandies(int[] candies, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int c : candies) freq.put(c, freq.getOrDefault(c, 0) + 1);

        int n = candies.length;
        for (int i = 0; i < k; i++) {
            int count = freq.get(candies[i]) - 1;
            if (count == 0) freq.remove(candies[i]);
            else freq.put(candies[i], count);
        }

        int maxUnique = freq.size();

        for (int i = k; i < n; i++) {
            freq.put(candies[i - k], freq.getOrDefault(candies[i - k], 0) + 1);
            int count = freq.get(candies[i]) - 1;
            if (count == 0) freq.remove(candies[i]);
            else freq.put(candies[i], count);

            maxUnique = Math.max(maxUnique, freq.size());
        }
        return maxUnique;
    }
}

