var shareCandies = function(candies, k) {
    const freq = new Map();
    for (const c of candies) freq.set(c, (freq.get(c) || 0) + 1);

    const n = candies.length;
    for (let i = 0; i < k; i++) {
        const cnt = freq.get(candies[i]) - 1;
        if (cnt === 0) freq.delete(candies[i]);
        else freq.set(candies[i], cnt);
    }

    let maxUnique = freq.size;

    for (let i = k; i < n; i++) {
        freq.set(candies[i - k], (freq.get(candies[i - k]) || 0) + 1);
        const cnt = freq.get(candies[i]) - 1;
        if (cnt === 0) freq.delete(candies[i]);
        else freq.set(candies[i], cnt);

        maxUnique = Math.max(maxUnique, freq.size);
    }
    return maxUnique;
};
